$('.price-type-radio').on('change', function() {
    var productId = $(this).data('product-id');
    var priceType = $(this).val();
    var isBulkBuyer = $(this).data('bulk-buyer');

    var priceElement = $('#price-' + productId);
    var price = 0;

    if (isBulkBuyer && priceType === 'cash') {
        price = $(this).data('bulk-cash-price');
    } else if (isBulkBuyer && priceType === 'check') {
        price = $(this).data('bulk-check-price');
    } else if (priceType === 'cash') {
        price = $(this).data('retail-cash-price');
    } else {
        price = $(this).data('retail-check-price');
    }

    priceElement.text(formatPrice(price));
});
